css:
:root{--k:#080808;--k2:#111111;--w:#F7F7F5;--g:#F3F4F6;--l:#C7FF3F;--ink:#1a1a1a;--mute:#5f6368;--line:#e2e3e0;--dline:#26262a;--dmute:#a1a1a6;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px);color-scheme:light}
html{scroll-behavior:smooth;scroll-padding-top:80px}
*,*::before,*::after{box-sizing:inherit}
body{margin:0;font:400 16px/1.6 Inter,system-ui,sans-serif;color:var(--ink);background:var(--w);-webkit-font-smoothing:antialiased;overflow-x:clip}
h1,h2,h3,h4,h5{font-family:Sora,Manrope,sans-serif;margin:0;line-height:1.1;letter-spacing:-.025em}
p{margin:0}a{color:inherit;text-decoration:none}ol,ul{margin:0;padding:0;list-style:none}
:focus-visible{outline:2px solid var(--l);outline-offset:3px;box-shadow:0 0 0 4px var(--k)}
.wrap{max-width:1200px;margin:0 auto;padding:0 24px;position:relative;z-index:1}
section{padding:96px 0;position:relative}
.dk{background:var(--k);color:#fff}.lt{background:var(--w);color:var(--ink)}.gr{background:var(--g);color:var(--ink)}
.dk p{color:var(--dmute)}.lt p,.gr p{color:var(--mute)}
.btn{display:inline-flex;align-items:center;gap:8px;padding:14px 22px;border-radius:999px;font:600 15px Inter;border:1.5px solid transparent;cursor:pointer;transition:transform .15s,background .15s}
.btn:hover{transform:translateY(-2px)}.btn.xl{padding:18px 32px;font-size:17px}
.b-l{background:var(--l);color:var(--k)}.b-o{border-color:#ffffff40;color:#fff}.b-o:hover{background:#ffffff14}.b-d{background:var(--k);color:#fff}
.ctas{display:flex;flex-wrap:wrap;gap:12px}
.eb{display:inline-flex;align-items:center;gap:10px;font:600 13px Inter;letter-spacing:.08em;margin-bottom:22px}
.eb::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--l)}
.dk .eb{color:var(--l)}.lt .eb,.gr .eb{color:var(--ink)}.lt .eb::before,.gr .eb::before{background:var(--k)}
.h2{font-size:clamp(30px,4.4vw,56px);letter-spacing:-.035em;line-height:1.05}
nav{position:sticky;top:0;z-index:30;background:#080808f2;color:#fff;border-bottom:1px solid var(--dline)}
nav .wrap{display:flex;align-items:center;justify-content:space-between;height:68px}
.logo{font:700 21px Sora;letter-spacing:-.03em}.logo i{font-style:normal;color:var(--l)}
nav ul{display:flex;gap:30px;font-size:14.5px;color:#d0d0d4}
nav ul a:hover,nav ul a.on{color:var(--l)}nav .btn{padding:10px 18px;font-size:14px}
/* motion */
.js .rv{opacity:0;transform:translateY(26px);transition:opacity .7s ease,transform .7s ease;transition-delay:var(--d,0s)}
.js .rv.in{opacity:1;transform:none}
.mk{display:block;overflow:hidden;padding-bottom:.1em;margin-bottom:-.1em}.mk>span{display:block}
.js .mk>span{transform:translateY(110%);transition:transform .9s cubic-bezier(.2,.7,.2,1);transition-delay:var(--d,0s)}
.js .in .mk>span,.js .mk.in>span{transform:none}
/* hero */
.hero{padding:88px 0 72px;background:radial-gradient(circle at 90% 0,#C7FF3F12,transparent 45%),var(--k)}
.hero h1{font-size:clamp(36px,6.2vw,84px);line-height:1.01;letter-spacing:-.045em;max-width:900px}
.hero h1 .m{color:var(--l)}
.hero .sub{margin:26px 0 34px;font-size:clamp(17px,2vw,20px);max-width:600px;color:#d6d6da}
.rail{display:grid;grid-template-columns:repeat(7,1fr);margin-top:72px}
.rail li{position:relative;padding-right:10px}
.rail li::before{content:"";display:block;width:14px;height:14px;border-radius:50%;background:var(--k);border:2px solid var(--l);margin-bottom:14px;position:relative;z-index:1}
.rail li::after{content:"";position:absolute;left:18px;right:4px;top:6px;height:2px;background:var(--l);opacity:.5;transform-origin:left;transition:transform .8s ease;transition-delay:calc(var(--d,0s) + .3s)}
.js .rail:not(.in) li::after{transform:scaleX(0)}
.rail li:last-child::after{display:none}
.rail b{display:block;font:600 11.5px Inter;letter-spacing:.08em;color:#fff}.rail small{color:var(--dmute);font-size:12px}
/* method */
.mh{max-width:640px;margin-bottom:56px}.mh p{margin-top:16px;font-size:17px}
.md li{display:grid;grid-template-columns:1fr auto;align-items:center;gap:24px;padding:22px 0;border-top:1px solid var(--line);transition:padding-left .3s}
.md li:hover{padding-left:14px}
.md li:last-child{border-bottom:1px solid var(--line)}
.md li b{font:700 clamp(36px,8.4vw,112px)/1 Sora;letter-spacing:-.05em}
.md li:last-child b span{background:linear-gradient(var(--l),var(--l)) 0 88%/100% .28em no-repeat}
.md li small{font-size:15px;color:var(--mute);max-width:220px;text-align:right}
.md .ar{display:block;font:600 22px Sora;color:var(--mute);padding:2px 0}
/* stage */
.sg .wrap{display:grid;grid-template-columns:1fr 1.15fr;gap:56px;align-items:center}
.sg.rev .tx{order:2}
.num{font:700 clamp(60px,8vw,104px)/1 Sora;letter-spacing:-.05em;-webkit-text-stroke:1.5px currentColor;color:transparent;opacity:.45;margin-bottom:4px}
.tag{font:600 13px Inter;letter-spacing:.1em;margin-bottom:14px}.dk .tag{color:var(--l)}
.sg h2{font-size:clamp(28px,3.6vw,46px);letter-spacing:-.035em;margin-bottom:24px}
.act{display:grid;grid-template-columns:1fr 1fr;gap:0 20px;margin-bottom:26px}
.act li{padding:10px 0;border-top:1px solid var(--line);font-size:15px;display:flex;gap:10px;color:var(--ink)}.dk .act li{border-color:var(--dline);color:#e0e0e4}
.act li::before{content:"";width:6px;height:6px;border-radius:50%;background:var(--k);margin-top:9px;flex:none}.dk .act li::before{background:var(--l)}
.out{border-left:3px solid var(--l);background:#fff;border-radius:0 14px 14px 0;padding:16px 20px}.dk .out{background:var(--k2)}
.out>b{display:block;font:600 11.5px Inter;letter-spacing:.1em;color:var(--mute);margin-bottom:10px}
.out ul{display:flex;flex-wrap:wrap;gap:8px}.out li{font:600 13.5px Sora;padding:7px 14px;border-radius:99px;background:var(--k);color:#fff}
.sg .tx>p{font-size:17px;max-width:460px;margin-bottom:22px}
/* panels */
.pn{border-radius:28px;padding:30px;background:var(--k);position:relative;overflow:hidden;color:#fff}
.dk .pn{background:var(--k2);border:1px solid var(--dline)}
.pn .cap{margin-top:14px;font-size:12.5px;color:var(--dmute)}
.nb{background:var(--k2);border:1px solid var(--dline);border-radius:14px;padding:12px 14px;font-size:13px;color:#fff;font-weight:500}
.dk .nb{background:var(--k)}.nb.a{border-color:var(--l);box-shadow:0 0 0 4px #C7FF3F1a}
.nb small{display:block;font-weight:400;font-size:11.5px;color:var(--dmute);margin-top:3px}
.ln{height:7px;border-radius:4px;background:#2a2a2e;margin-top:8px}.ln.w{height:11px;width:60%;background:#e9e9ea}.ln.s{width:55%}
.pill{display:inline-block;padding:6px 13px;border-radius:99px;background:var(--l);color:var(--k);font:600 11px Inter;white-space:nowrap}
.ch{font-size:11px;padding:4px 10px;border-radius:99px;background:#1b1b1f;border:1px solid var(--dline);color:#d8d8dc}
.io{display:grid;grid-template-columns:1fr 36px 1fr;gap:6px;align-items:center}
.io .c{display:flex;flex-direction:column;gap:10px}.io .ar{color:var(--l);font:600 22px Sora;text-align:center}
.io .o{padding:20px 16px}.io .o h5{font-size:16px;margin-bottom:12px}.io .o .chs{display:flex;flex-wrap:wrap;gap:6px;margin-top:14px}
.bd3{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.bd3 h6{margin:0 0 10px;font:600 11px Inter;letter-spacing:.08em;color:var(--dmute)}
.bd3>div{display:flex;flex-direction:column;gap:8px}
.ms{position:relative;display:grid;grid-template-columns:repeat(4,1fr);margin-top:30px;padding-top:18px}
.ms::before{content:"";position:absolute;left:6px;right:6px;top:6px;height:2px;background:linear-gradient(90deg,var(--l),#2a2a2e)}
.ms span{font-size:11.5px;color:var(--dmute);position:relative}.ms span::before{content:"";position:absolute;left:0;top:-18px;width:12px;height:12px;border-radius:50%;background:var(--k);border:2px solid var(--l)}
.tr{display:grid;grid-template-columns:1fr 38px 1fr;gap:6px;align-items:center}.tr .arr{color:var(--l);font:600 24px Sora;text-align:center}
.wf{background:#fff;border:1.5px dashed #b9bbb6;border-radius:12px;padding:14px;color:#666}
.wf .bar{height:10px;border-radius:3px;border:1.5px solid #b9bbb6;margin-bottom:10px;width:100%}.wf .hb{height:84px;border:1.5px solid #b9bbb6;margin-bottom:10px;background:linear-gradient(to top right,transparent calc(50% - 1px),#c9cbc6,transparent calc(50% + 1px)),linear-gradient(to bottom right,transparent calc(50% - 1px),#c9cbc6,transparent calc(50% + 1px))}
.wf .r3{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:10px}.wf .r3 i{height:34px;border:1.5px solid #b9bbb6}.wf .bt{width:42%;height:20px;border:1.5px solid #b9bbb6;border-radius:20px}
.ui{background:var(--k);border:1px solid var(--dline);border-radius:12px;padding:14px;box-shadow:0 18px 36px #0008}
.dk .ui{background:var(--k)}
.ui .nv{display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;font:700 11px Sora}.ui .nv em{font-style:normal;background:var(--l);color:var(--k);padding:3px 9px;border-radius:99px;font:600 9px Inter}
.ui .hb{height:84px;border-radius:9px;background:linear-gradient(135deg,#25252a,#141416);border:1px solid #333;padding:12px;margin-bottom:10px}
.ui .r3{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:10px}.ui .r3 i{height:34px;border-radius:7px;background:#1c1c20;border:1px solid var(--dline)}
.lab{font:600 11px Inter;letter-spacing:.08em;margin-top:10px;display:block;color:var(--dmute)}
.arch{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.arch .full{grid-column:1/-1}.arch .nb{padding:14px}.arch .nb b{font:600 13.5px Sora}
.fe{display:grid;grid-template-columns:1.2fr 1fr;gap:16px;align-items:center}
.fe .mini{background:#17171a;border:1px solid var(--dline);border-radius:10px;padding:10px}
.tb{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:12px 16px;border-radius:12px;border:1px dashed #3a3a40;font-size:13px;color:#d8d8dc}
.qa{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.qa .nb{display:flex;align-items:center;gap:12px}.ck{flex:none;width:22px;height:22px;border-radius:7px;background:var(--l);color:var(--k);display:grid;place-items:center;font:700 12px Inter}
.bw{border:1px solid var(--dline);border-radius:14px;overflow:hidden;background:var(--k2);margin-bottom:20px}
.bw .top{display:flex;align-items:center;gap:6px;padding:10px 14px;border-bottom:1px solid var(--dline)}.bw .top b{width:9px;height:9px;border-radius:50%;background:#333}.bw .top .url{margin-left:10px;font-size:12px;color:var(--dmute);background:#1a1a1e;border-radius:99px;padding:3px 14px;flex:1;max-width:220px}
.bw .bd{padding:16px;display:flex;justify-content:space-between;align-items:flex-start;gap:16px}.bw .bd div:first-child{flex:1}
.tl{position:relative}
.tl li{position:relative;padding:0 0 16px 34px;font-size:14.5px;color:#e4e4e7}
.tl li::before{content:"";position:absolute;left:0;top:3px;width:14px;height:14px;border-radius:50%;background:var(--k);border:2px solid var(--l)}
.tl li::after{content:"";position:absolute;left:6px;top:20px;bottom:2px;width:2px;background:#2a2a2e}.tl li:last-child::after{display:none}.tl li:last-child{padding-bottom:0}
.tl li:last-child::before{background:var(--l)}
.cy{display:flex;align-items:stretch;gap:0}
.cy .nb{flex:1;text-align:center;padding:16px 8px;margin-right:24px;position:relative}.cy .nb:last-child{margin-right:0;border-color:var(--l)}
.cy .nb::after{content:"→";position:absolute;left:100%;top:50%;width:24px;transform:translateY(-50%);text-align:center;color:var(--l);font:600 15px Sora}.cy .nb:last-child::after{display:none}
.rt{margin-top:14px;border:1.5px solid var(--l);border-top:0;border-radius:0 0 16px 16px;padding:12px;text-align:center;font-size:13px;color:var(--l);opacity:.85;margin-left:6%;margin-right:6%}
/* comm */
.cm{display:grid;grid-template-columns:repeat(4,1fr);gap:0;margin-top:52px}
.cm div{padding:28px 24px 0 0;border-top:2px solid var(--k);transition:transform .25s}.cm div:hover{transform:translateY(-4px)}
.cm span{font:600 13px Sora;color:var(--mute)}.cm h3{font-size:22px;margin:30px 0 10px}.cm p{font-size:15px;max-width:240px}
/* needs */
.nd{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:48px}
.nd li{display:flex;gap:18px;align-items:flex-start;background:#fff;border:1px solid var(--line);border-radius:18px;padding:22px;transition:transform .25s,border-color .25s}
.nd li:hover{transform:translateY(-3px);border-color:var(--k)}
.nd .bx{flex:none;width:26px;height:26px;border-radius:8px;border:2px solid var(--k);display:grid;place-items:center;font:700 13px Inter;margin-top:1px}.nd .bx::before{content:"✓";color:var(--k)}
.nd h3{font-size:18px;margin-bottom:4px}.nd p{font-size:15px}
/* cta */
.cta{background:var(--l);color:var(--k);padding:112px 0}
.cta h2{font-size:clamp(38px,7vw,92px);letter-spacing:-.045em;line-height:1;max-width:900px;margin-bottom:38px}
footer{background:var(--k);color:#fff;padding:72px 0 32px}
.fg{display:grid;grid-template-columns:1.6fr repeat(4,1fr);gap:36px}
footer p,footer li,footer a{color:var(--dmute);font-size:14.5px}footer h4{font-size:14px;margin-bottom:14px}
footer li{padding:5px 0}footer a:hover{color:var(--l)}
.fb{margin-top:48px;padding-top:24px;border-top:1px solid var(--dline);display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;font-size:13.5px;color:var(--dmute)}
.big{font:700 clamp(40px,12vw,150px)/1 Sora;letter-spacing:-.05em;color:#161618;margin-top:40px;white-space:nowrap;overflow:hidden}
/* tablet */
@media(max-width:1020px){
.sg .wrap{grid-template-columns:1fr;gap:36px}.sg.rev .tx{order:0}.sg .tx>p{max-width:none}
.cm{grid-template-columns:1fr 1fr;row-gap:30px}.fg{grid-template-columns:1fr 1fr 1fr}
.rail{grid-template-columns:repeat(4,1fr);row-gap:28px}.rail li:nth-child(4)::after{display:none}}
@media(max-width:860px){nav ul{display:none}.md li small{display:none}.md li{grid-template-columns:1fr}}
/* mobile */
@media(max-width:600px){
section{padding:68px 0}.wrap{padding:0 20px}.hero{padding:56px 0 52px}.hero .rail{margin-top:52px}
.rail{grid-template-columns:1fr 1fr}.rail li::after{display:none}
.act,.qa,.nd,.cm{grid-template-columns:1fr}.pn{padding:18px}
.io,.tr{grid-template-columns:1fr}.io .ar,.tr .arr{transform:rotate(90deg);padding:4px 0}
.bd3{grid-template-columns:1fr}.arch{grid-template-columns:1fr}.fe{grid-template-columns:1fr}
.cy{flex-direction:column}.cy .nb{margin:0 0 24px}.cy .nb::after{content:"↓";left:50%;top:100%;transform:translateX(-50%);height:24px;line-height:24px;width:auto}
.rt{margin:0}.ms span{font-size:10.5px}.ctas .btn{width:100%;justify-content:center}.fg{grid-template-columns:1fr 1fr}.fg>div:first-child{grid-column:span 2}.cta{padding:76px 0}}
@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important;scroll-behavior:auto!important}.js .rv,.js .mk>span{opacity:1;transform:none}.js .rail li::after{transform:none}}

js:
(function(){
  var els=document.querySelectorAll('.rv');
  if(!('IntersectionObserver' in window)||window.matchMedia('(prefers-reduced-motion: reduce)').matches){
    els.forEach(function(e){e.classList.add('in')});return;
  }
  var io=new IntersectionObserver(function(es){
    es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}});
  },{threshold:.12,rootMargin:'0px 0px -6% 0px'});
  els.forEach(function(e){io.observe(e)});
})();
